struct composed {struct test*h;struct nwn n;struct nst_profile profile;};
static int entropy(void*c,uint8_t*p,size_t n){(void)c;assert(n==32);memcpy(p,sn,n);return 0;}
static int native_peer(void*c,const struct stc_action*a,const struct stc*s){struct composed*x=c;assert(s==&x->n.owner.transaction);unsigned kind=a->kind==STC_PREPARE_PEER?NST_PREPARE_PEER:a->kind==STC_CONFIGURE_PEER?NST_CONFIGURE_PEER:NST_RETIRE_PEER;return nst_peer_begin(&x->h->s,a->ticket,kind,kind==NST_PREPARE_PEER?&x->profile:NULL,kind==NST_CONFIGURE_PEER?a->payload:NULL,kind==NST_CONFIGURE_PEER?a->bytes:0);}
static int native_event(void*c,const struct nst_event*e){struct composed*x=c;C(x->h->s.phase==NST_IDLE);x->h->events[e->kind]++;unsigned type=e->kind==NST_PEER_PREPARED?NWO_PREPARED:e->kind==NST_PEER_CONFIGURED?NWO_CONFIGURED:e->kind==NST_PEER_RETIRED?NWO_RETIRED:0;if(type)return nwn_peer_complete(&x->n,e->generation,e->ticket,type,e->status==0,x->h->now/1000)<0?-1:0;return nwn_event(&x->n,e,x->h->now/1000)<0?-1:0;}
static void advance(struct composed*x){C(nwn_pump(&x->n,x->h->now/1000)>=0);C(!nst_step(&x->h->s,&io,x->h,16,native_event,x));x->h->now+=1000;}
static void phase(struct composed*x,unsigned target){for(unsigned k=0;k<200&&x->n.owner.transaction.phase!=target;k++)advance(x);if(x->n.owner.transaction.phase!=target)fprintf(stderr,"wanted phase%u got%u transporthalt%u err%u\n",target,x->n.owner.transaction.phase,x->h->s.halt,x->h->s.error);C(x->n.owner.transaction.phase==target);}
static void management(struct composed*x,const uint8_t*m,size_t n){uint8_t p[256]={0};assert(n+24<=sizeof p);put16(p,n+24);put16(p+2,2u<<11);put32(p+4,x->h->s.peer.wlan);put32(p+8,12u<<8);memcpy(p+24,m,n);deliver(x->h,0,p,n+24);}
static void eapol_rx(struct composed*x,const uint8_t*m,size_t n){uint8_t p[1024]={0};assert(n+54<=sizeof p);put16(p,n+54);put16(p+2,2u<<11);put32(p+4,x->h->s.peer.wlan|(8u<<11));put32(p+8,1u<<13);put16(p+24,0x0208);memcpy(p+26,peer,6);memcpy(p+40,own,6);memcpy(p+46,peer,6);p[52]=0x88;p[53]=0x8e;memcpy(p+54,m,n);deliver(x->h,0,p,n+54);}
