if(scenario==5){h->now=29995000;h->defer_air=1;h->defer_dma=1;eapol_rx(&x,m1,sizeof m1);advance(&x);advance(&x);C(x.n.owner.in_ticket&&h->s.wire_busy&&!h->s.dma_done);h->now=30002000;advance(&x);C(x.n.owner.transaction.outcome==STC_TIMEOUT&&!h->s.halt&&x.n.owner.in_ticket);unsigned slot=h->s.tx_next;put32(at(h,h->init.transport.tx_ring+16u*slot+4,4),0xc0000000);h->didx=h->cidx;h->defer_dma=h->defer_air=0;phase(&x,STC_DONE);C(!h->s.controlled_port&&!nwo_authorized(&x.n.owner));cleanup(h);free(h);continue;}
